package tn.esprit.autoloc.service.impl;

import jakarta.persistence.EntityNotFoundException;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import tn.esprit.autoloc.domain.Reservation;
import tn.esprit.autoloc.repository.ReservationRepository;
import tn.esprit.autoloc.service.interfaces.IReservationService;

import java.util.List;

@Service
@RequiredArgsConstructor
public class ReservationServiceImpl implements IReservationService {

    // Injected by Spring (constructor injection, generated by Lombok)
    private final ReservationRepository repository;

    @Override
    public List<Reservation> retrieveAllReservations() {
        return repository.findAll();
    }

    @Override
    public Reservation retrieveReservation(Long id) {
        return repository.findById(id)
                .orElseThrow(() -> new EntityNotFoundException("Reservation not found with id " + id));
    }

    @Override
    public Reservation addReservation(Reservation entity) {
        return repository.save(entity);
    }

    @Override
    public Reservation modifyReservation(Reservation entity) {
        return repository.save(entity);
    }

    @Override
    public void removeReservation(Long id) {
        repository.deleteById(id);
    }
}